import React from 'react';
import { useQuery } from '@tanstack/react-query';
import { motion } from 'framer-motion';
import { Package, CheckCircle, Clock, TrendingUp, DollarSign } from 'lucide-react';
import orderService from '../../services/orderService';
import commissionService from '../../services/commissionService';
import StatCard from '../../components/ui/StatCard';
import SectionCard from '../../components/ui/SectionCard';

const Overview = () => {
    const { data: stats, isLoading: statsLoading } = useQuery({
        queryKey: ['sales-rep-stats'],
        queryFn: orderService.getSalesRepStats
    });

    const { data: earnings, isLoading: earningsLoading } = useQuery({
        queryKey: ['my-earnings'],
        queryFn: commissionService.getMyEarnings
    });

    return (
        <div className="space-y-6">
            <div>
                <h1 className="text-2xl font-bold text-brand-800 dark:text-white">Welcome back!</h1>
                <p className="text-slate-500 mt-1">Here's your performance overview.</p>
            </div>

            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
                <StatCard label="Total Orders" value={stats?.totalOrders || 0} icon={Package} color="navy" loading={statsLoading} />
                <StatCard label="Completed" value={stats?.completedOrders || 0} icon={CheckCircle} color="emerald" loading={statsLoading} subtitle={`${stats?.completionRate || 0}% completion`} />
                <StatCard label="Total Revenue" value={`$${(stats?.totalRevenue || 0).toLocaleString()}`} icon={DollarSign} color="gold" loading={statsLoading} />
                <StatCard label="Active Orders" value={stats?.activeOrders || 0} icon={Clock} color="teal" loading={statsLoading} />
            </div>

            <SectionCard title="My Earnings" subtitle="Commission structure summary">
                {earnings?.config ? (
                    <div className="grid grid-cols-3 gap-4 text-center">
                        <div className="p-4 bg-slate-50 dark:bg-brand-800/50 rounded-xl">
                            <p className="text-xs text-slate-500 mb-1">Structure</p>
                            <p className="font-bold text-brand-800 dark:text-white capitalize">{earnings.config.structure?.replace(/_/g, ' ')}</p>
                        </div>
                        {earnings.config.baseSalary > 0 && (
                            <div className="p-4 bg-slate-50 dark:bg-brand-800/50 rounded-xl">
                                <p className="text-xs text-slate-500 mb-1">Base Salary</p>
                                <p className="font-bold text-brand-800 dark:text-white">${earnings.config.baseSalary}/mo</p>
                            </div>
                        )}
                        {earnings.config.commissionPercentage > 0 && (
                            <div className="p-4 bg-slate-50 dark:bg-brand-800/50 rounded-xl">
                                <p className="text-xs text-slate-500 mb-1">Commission</p>
                                <p className="font-bold text-brand-800 dark:text-white">{earnings.config.commissionPercentage}%</p>
                            </div>
                        )}
                    </div>
                ) : (
                    <p className="text-slate-500 text-center py-4">No commission structure configured yet.</p>
                )}
            </SectionCard>
        </div>
    );
};

export default Overview;
